"use client"

import * as React from "react"
import { MoreHorizontalIcon, SearchIcon } from "lucide-react"

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Kbd } from "@/components/ui/kbd"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupAction,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
  SidebarSeparator,
} from "@/components/ui/sidebar"
import { useControllableState } from "@/hooks/use-controllable-state"

import { AccountMenu } from "./account-menu"
import { formatLabel, resolveLabels, type Sidebar02Labels } from "./config"
import {
  DEFAULT_ACCOUNTS,
  DEFAULT_FOOTER_ITEMS,
  DEFAULT_NAV_GROUPS,
  DEFAULT_QUICK_ACTIONS,
  DEFAULT_TEAMS,
} from "./nav-data"
import {
  NavLinkItem,
  NavigationContext,
  ROW_CLASS,
  type NavigationValue,
} from "./navigation"
import { SearchCommand } from "./search-command"
import {
  formatShortcut,
  useIsApplePlatform,
  useModifierHotkey,
} from "./shortcuts"
import { TeamSwitcher } from "./team-switcher"
import type {
  Sidebar02Account,
  Sidebar02AccountAction,
  Sidebar02GroupAction,
  Sidebar02NavGroup,
  Sidebar02NavItem,
  Sidebar02NavigateSource,
  Sidebar02QuickAction,
  Sidebar02Team,
} from "./types"

/** 分组标题 + 右侧「更多」菜单 + 导航项。 */
function NavGroup({
  group,
  labels,
  onGroupAction,
}: {
  group: Sidebar02NavGroup
  labels: Sidebar02Labels
  onGroupAction?: (payload: {
    groupId: string
    action: Sidebar02GroupAction
  }) => void
}) {
  const labelId = React.useId()
  return (
    <>
      {group.label ? (
        // 收起成图标后标题会隐藏，用一条细线保留分组边界
        <SidebarSeparator className="mx-2 hidden w-auto group-data-[collapsible=icon]:block" />
      ) : null}
      <SidebarGroup
        data-slot="sidebar-02-nav-group"
        role={group.label ? "group" : undefined}
        aria-labelledby={group.label ? labelId : undefined}
      >
        {group.label ? (
          <SidebarGroupLabel id={labelId}>{group.label}</SidebarGroupLabel>
        ) : null}
        {group.label && group.actionable ? (
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <SidebarGroupAction
                  aria-label={formatLabel(labels.groupMore, {
                    group: group.label,
                  })}
                  className="data-popup-open:bg-sidebar-accent"
                />
              }
            >
              <MoreHorizontalIcon aria-hidden="true" />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="start"
              side="bottom"
              className="min-w-40"
            >
              <DropdownMenuItem
                onClick={() =>
                  onGroupAction?.({ groupId: group.id, action: "manage" })
                }
              >
                {labels.groupManage}
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() =>
                  onGroupAction?.({ groupId: group.id, action: "hide" })
                }
              >
                {labels.groupHide}
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        ) : null}
        <SidebarGroupContent>
          <SidebarMenu>
            {group.items.map((item) => (
              <NavLinkItem
                key={item.id}
                item={item}
                newWindowLabel={labels.newWindow}
              />
            ))}
          </SidebarMenu>
        </SidebarGroupContent>
      </SidebarGroup>
    </>
  )
}

type Sidebar02Props = Omit<
  React.ComponentProps<typeof Sidebar>,
  "children" | "collapsible"
> & {
  /** 团队列表 */
  teams?: Sidebar02Team[]
  /** 受控的当前团队 id */
  activeTeamId?: string
  /** 非受控时的初始团队 id，默认第一个团队 */
  defaultActiveTeamId?: string
  /** 团队切换时回调（点选或按 ⌘1…⌘9），参数是新团队的 id */
  onTeamChange?: (teamId: string) => void
  onCreateTeam?: () => void
  /** 账号列表 */
  accounts?: Sidebar02Account[]
  /** 受控的当前账号 id */
  activeAccountId?: string
  /** 非受控时的初始账号 id，默认第一个账号 */
  defaultActiveAccountId?: string
  /** 账号切换时回调，参数是新账号的 id */
  onAccountChange?: (accountId: string) => void
  /** 点击个人资料、账号设置、设备管理时回调 */
  onAccountAction?: (payload: { action: Sidebar02AccountAction }) => void
  onAddAccount?: () => void
  onSignOut?: () => void
  /** 主导航分组 */
  groups?: Sidebar02NavGroup[]
  /** 底部的次要入口 */
  footerItems?: Sidebar02NavItem[]
  /** 受控的当前导航项 id */
  activeItemId?: string
  /** 非受控时的初始导航项 id，默认第一个导航项 */
  defaultActiveItemId?: string
  /** 当前导航项变化时回调 */
  onActiveItemChange?: (itemId: string) => void
  /** 渲染链接的组件，默认 "a"；用 Next.js 时传入 next/link 的 Link */
  linkComponent?: React.ElementType
  /** 点击导航项或在搜索里回车选中时回调 */
  onNavigate?: (payload: {
    href: string
    itemId: string
    source: Sidebar02NavigateSource
  }) => void
  /** 为 true 时拦截浏览器跳转，交给 onNavigate 处理（单页应用路由、预览演示） */
  interceptNavigation?: boolean
  /** 分组「更多」菜单的回调 */
  onGroupAction?: (payload: {
    groupId: string
    action: Sidebar02GroupAction
  }) => void
  /** 搜索弹窗里的快捷操作 */
  quickActions?: Sidebar02QuickAction[]
  onQuickAction?: (payload: { actionId: string }) => void
  /** 受控的搜索弹窗开关 */
  searchOpen?: boolean
  defaultSearchOpen?: boolean
  onSearchOpenChange?: (open: boolean) => void
  /** 收起方式：icon 收成图标栏（默认），offcanvas 整个滑出，none 不可收起 */
  collapsible?: "icon" | "offcanvas" | "none"
  labels?: Partial<Sidebar02Labels>
}

/**
 * 团队与账号切换侧栏：顶部团队切换 + 搜索入口，中间分组导航，底部次要入口与用户卡。
 * 基于 shadcn 官方 Sidebar：收起成图标、移动端抽屉、⌘B 收起都沿用官方行为。
 * 团队、账号、当前项、搜索弹窗都同时支持受控与非受控。
 */
function Sidebar02({
  teams = DEFAULT_TEAMS,
  activeTeamId: activeTeamIdProp,
  defaultActiveTeamId,
  onTeamChange,
  onCreateTeam,
  accounts = DEFAULT_ACCOUNTS,
  activeAccountId: activeAccountIdProp,
  defaultActiveAccountId,
  onAccountChange,
  onAccountAction,
  onAddAccount,
  onSignOut,
  groups = DEFAULT_NAV_GROUPS,
  footerItems = DEFAULT_FOOTER_ITEMS,
  activeItemId: activeItemIdProp,
  defaultActiveItemId,
  onActiveItemChange,
  linkComponent = "a",
  onNavigate,
  interceptNavigation = false,
  onGroupAction,
  quickActions = DEFAULT_QUICK_ACTIONS,
  onQuickAction,
  searchOpen: searchOpenProp,
  defaultSearchOpen = false,
  onSearchOpenChange,
  collapsible = "icon",
  labels,
  ...props
}: Sidebar02Props) {
  const text = resolveLabels(labels)
  const isApple = useIsApplePlatform()

  const [activeTeamId, setActiveTeamId] = useControllableState<
    string | undefined
  >({
    prop: activeTeamIdProp,
    defaultProp: defaultActiveTeamId ?? teams[0]?.id,
    onChange: (value) => value !== undefined && onTeamChange?.(value),
  })
  const [activeAccountId, setActiveAccountId] = useControllableState<
    string | undefined
  >({
    prop: activeAccountIdProp,
    defaultProp: defaultActiveAccountId ?? accounts[0]?.id,
    onChange: (value) => value !== undefined && onAccountChange?.(value),
  })
  const [activeItemId, setActiveItemId] = useControllableState<
    string | undefined
  >({
    prop: activeItemIdProp,
    defaultProp: defaultActiveItemId ?? groups[0]?.items[0]?.id,
    onChange: (value) => value !== undefined && onActiveItemChange?.(value),
  })
  const [searchOpen, setSearchOpen] = useControllableState({
    prop: searchOpenProp,
    defaultProp: defaultSearchOpen,
    onChange: onSearchOpenChange,
  })

  // ⌘/Ctrl + 1…9 切换团队。放在 Sidebar02 顶层而不是下拉菜单里：移动端抽屉关着时组件已卸载，菜单没打开时也要能用
  useModifierHotkey(
    (key) => /^[1-9]$/.test(key) && Number(key) <= teams.length,
    (key) => {
      const team = teams[Number(key) - 1]
      if (team) setActiveTeamId(team.id)
    },
    !searchOpen,
  )
  useModifierHotkey(
    (key) => key.toLowerCase() === "k",
    () => setSearchOpen((open) => !open),
  )

  const navigate = React.useCallback(
    (item: Sidebar02NavItem, source: Sidebar02NavigateSource) => {
      if (item.external) {
        if (source === "search") window.open(item.href, "_blank", "noreferrer")
        return
      }
      setActiveItemId(item.id)
      onNavigate?.({ href: item.href, itemId: item.id, source })
      // 从搜索里选中时没有真正的链接点击，不拦截就要自己跳转
      if (source === "search" && !interceptNavigation)
        window.location.assign(item.href)
    },
    [interceptNavigation, onNavigate, setActiveItemId],
  )

  const navigation = React.useMemo<NavigationValue>(
    () => ({ linkComponent, activeItemId, interceptNavigation, navigate }),
    [linkComponent, activeItemId, interceptNavigation, navigate],
  )

  return (
    <NavigationContext.Provider value={navigation}>
      <Sidebar collapsible={collapsible} {...props}>
        {/* 团队带高 56px（h-14），底线与右侧顶栏的底线连成一条 */}
        <SidebarHeader className="h-14 shrink-0 justify-center border-b border-sidebar-border p-1 group-data-[collapsible=icon]:p-2">
          <TeamSwitcher
            teams={teams}
            activeTeamId={activeTeamId}
            onTeamChange={setActiveTeamId}
            onCreateTeam={onCreateTeam}
            labels={text}
          />
        </SidebarHeader>
        <div className="shrink-0 border-b border-sidebar-border p-2">
          <SidebarMenu data-slot="sidebar-02-search">
            <SidebarMenuItem>
              <SidebarMenuButton
                variant="outline"
                tooltip={text.searchTooltip}
                aria-keyshortcuts="Meta+K Control+K"
                aria-haspopup="dialog"
                className={`${ROW_CLASS} text-sidebar-foreground/70`}
                onClick={() => setSearchOpen(true)}
              >
                <SearchIcon aria-hidden="true" />
                <span>{text.searchButton}</span>
                <Kbd className="ml-auto group-data-[collapsible=icon]:hidden">
                  {formatShortcut("K", isApple)}
                </Kbd>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </div>
        <SidebarContent>
          <nav aria-label={text.navLabel} className="flex flex-col">
            {groups.map((group) => (
              <NavGroup
                key={group.id}
                group={group}
                labels={text}
                onGroupAction={onGroupAction}
              />
            ))}
          </nav>
        </SidebarContent>
        <SidebarFooter className="border-t border-sidebar-border">
          <nav aria-label={text.footerNavLabel}>
            <SidebarMenu>
              {footerItems.map((item) => (
                <NavLinkItem
                  key={item.id}
                  item={item}
                  newWindowLabel={text.newWindow}
                />
              ))}
            </SidebarMenu>
          </nav>
          <AccountMenu
            accounts={accounts}
            activeAccountId={activeAccountId}
            onAccountChange={setActiveAccountId}
            onAccountAction={onAccountAction}
            onAddAccount={onAddAccount}
            onSignOut={onSignOut}
            labels={text}
          />
        </SidebarFooter>
        {collapsible === "icon" ? <SidebarRail /> : null}
      </Sidebar>
      <SearchCommand
        open={searchOpen}
        onOpenChange={setSearchOpen}
        groups={groups}
        footerItems={footerItems}
        quickActions={quickActions}
        onSelectItem={(item) => {
          setSearchOpen(false)
          navigate(item, "search")
        }}
        onSelectAction={(action) => {
          setSearchOpen(false)
          onQuickAction?.({ actionId: action.id })
        }}
        labels={text}
      />
    </NavigationContext.Provider>
  )
}

export { Sidebar02 }
export type { Sidebar02Props }

/**
 * 侧栏所有用户可见的文案。
 * 含 {name}、{group}、{plan} 的文案在渲染时由 formatLabel 填入实际值。
 */
const DEFAULT_LABELS = {
  // 团队切换
  switchTeam: "切换团队，当前：{name}（{plan}）",
  teamMenuTitle: "团队",
  newTeam: "新建团队",
  // 搜索
  searchButton: "搜索…",
  searchTooltip: "搜索",
  searchTitle: "搜索",
  searchDescription: "搜索页面和快捷操作，回车跳转。",
  searchPlaceholder: "搜索页面或操作…",
  searchEmpty: "没有找到相关结果",
  searchPages: "页面",
  searchActions: "快捷操作",
  // 导航
  navLabel: "主导航",
  footerNavLabel: "辅助导航",
  groupMore: "{group}的更多操作",
  groupManage: "管理分组",
  groupHide: "隐藏分组",
  newWindow: "（在新窗口打开）",
  // 账号
  accountTrigger: "账号菜单：{name}",
  profile: "个人资料",
  accountSettings: "账号设置",
  devices: "设备管理",
  switchAccount: "切换账号",
  addAccount: "添加账号",
  signOut: "退出登录",
} as const

type Sidebar02Labels = Record<keyof typeof DEFAULT_LABELS, string>

/** 合并用户传入的文案与默认文案。 */
function resolveLabels(labels?: Partial<Sidebar02Labels>): Sidebar02Labels {
  return { ...DEFAULT_LABELS, ...labels }
}

/** 把文案里的 {key} 占位符替换成实际值。 */
function formatLabel(
  template: string,
  values: Record<string, string | number>,
): string {
  return Object.entries(values).reduce(
    (text, [key, value]) => text.replaceAll(`{${key}}`, String(value)),
    template,
  )
}

export { DEFAULT_LABELS, formatLabel, resolveLabels }
export type { Sidebar02Labels }

import type { LucideIcon } from "lucide-react"

/** 团队：切换器里的一行。没有 icon 时用团队名的第一个字做标识。 */
type Sidebar02Team = {
  id: string
  name: string
  /** 套餐名，显示在团队名下方的小字 */
  plan: string
  icon?: LucideIcon
}

/** 账号：用户卡与「切换账号」列表里的一行。 */
type Sidebar02Account = {
  id: string
  name: string
  username: string
  email: string
  avatar?: string
}

/** 导航项。external 为 true 时在新窗口打开，且不会成为「当前项」。 */
type Sidebar02NavItem = {
  id: string
  label: string
  href: string
  icon: LucideIcon
  /** 右侧计数 */
  badge?: string | number
  external?: boolean
}

/** 导航分组。没有 label 的分组不显示标题。 */
type Sidebar02NavGroup = {
  id: string
  label?: string
  items: Sidebar02NavItem[]
  /** 在标题右侧显示「更多」菜单（需要同时有 label） */
  actionable?: boolean
}

/** 搜索弹窗里的快捷操作。 */
type Sidebar02QuickAction = {
  id: string
  label: string
  icon: LucideIcon
}

type Sidebar02GroupAction = "manage" | "hide"
type Sidebar02AccountAction = "profile" | "settings" | "devices"
type Sidebar02NavigateSource = "menu" | "search"

export type {
  Sidebar02Account,
  Sidebar02AccountAction,
  Sidebar02GroupAction,
  Sidebar02NavGroup,
  Sidebar02NavItem,
  Sidebar02NavigateSource,
  Sidebar02QuickAction,
  Sidebar02Team,
}

"use client"

import * as React from "react"
import { ExternalLinkIcon } from "lucide-react"

import {
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"

import type { Sidebar02NavItem, Sidebar02NavigateSource } from "./types"

type NavigationValue = {
  /** 渲染链接的组件，默认 "a"，可换成 Next 的 Link */
  linkComponent: React.ElementType
  activeItemId?: string
  /** 为 true 时拦截浏览器默认跳转，由 onNavigate 自行处理 */
  interceptNavigation: boolean
  /** 选中一个导航项：更新当前项、通知外部，必要时自己跳转 */
  navigate: (item: Sidebar02NavItem, source: Sidebar02NavigateSource) => void
}

const NavigationContext = React.createContext<NavigationValue | null>(null)

function useNavigation() {
  const value = React.useContext(NavigationContext)
  if (!value) throw new Error("导航组件必须放在 Sidebar02 内部使用")
  return value
}

/** 触屏上菜单行加高一档（32 → 40px）；收起成图标时保持 32px 方块。 */
const ROW_CLASS = "pointer-coarse:h-10"

/** 选中项左侧的细竖线，让当前位置不只靠底色表达。 */
const ACTIVE_BAR_CLASS =
  "relative before:absolute before:inset-y-1.5 before:left-0 before:w-0.5 before:rounded-full before:bg-sidebar-primary before:opacity-0 data-active:before:opacity-100"

/** 一行导航：链接 + 计数 + 外链图标，收起时用 Tooltip 显示名称。 */
function NavLinkItem({
  item,
  newWindowLabel,
}: {
  item: Sidebar02NavItem
  newWindowLabel: string
}) {
  const { linkComponent: LinkComponent, activeItemId, navigate, interceptNavigation } =
    useNavigation()
  const { isMobile, setOpenMobile } = useSidebar()
  const active = !item.external && item.id === activeItemId

  function handleClick(event: React.MouseEvent<HTMLAnchorElement>) {
    // 修饰键、非左键点击保留浏览器原生行为（新标签页等）
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    )
      return
    if (isMobile) setOpenMobile(false)
    if (item.external) return
    if (interceptNavigation) event.preventDefault()
    navigate(item, "menu")
  }

  const externalProps = item.external
    ? { target: "_blank", rel: "noreferrer" }
    : undefined

  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.label}
        className={cn(
          ROW_CLASS,
          ACTIVE_BAR_CLASS,
          item.badge !== undefined && "pr-10",
        )}
        render={
          <LinkComponent
            href={item.href}
            aria-current={active ? "page" : undefined}
            onClick={handleClick}
            {...externalProps}
          />
        }
      >
        <item.icon />
        <span className="truncate">
          {item.label}
          {item.external ? (
            <span className="sr-only">{newWindowLabel}</span>
          ) : null}
        </span>
        {item.external ? (
          <ExternalLinkIcon
            aria-hidden="true"
            className="ml-auto size-3.5! opacity-60 group-data-[collapsible=icon]:hidden"
          />
        ) : null}
      </SidebarMenuButton>
      {item.badge !== undefined ? (
        <SidebarMenuBadge className="tabular-nums pointer-coarse:top-2.5">
          {item.badge}
        </SidebarMenuBadge>
      ) : null}
    </SidebarMenuItem>
  )
}

export { NavLinkItem, NavigationContext, ROW_CLASS, useNavigation }
export type { NavigationValue }

"use client"

import * as React from "react"

const noopSubscribe = () => () => {}
const getIsApple = () => /Mac|iPhone|iPad/i.test(navigator.platform)
// 预渲染与水合阶段按 ⌘ 处理，挂载后再换成真实平台，避免水合不匹配
const getServerIsApple = () => true

/** 当前是否苹果平台，决定快捷键显示 ⌘ 还是 Ctrl。 */
function useIsApplePlatform() {
  return React.useSyncExternalStore(
    noopSubscribe,
    getIsApple,
    getServerIsApple,
  )
}

/** 把按键写成显示文本：苹果平台 ⌘1，其余 Ctrl 1。 */
function formatShortcut(key: string, isApple: boolean) {
  return isApple ? `⌘${key}` : `Ctrl ${key}`
}

/**
 * 注册 ⌘/Ctrl + 按键的全局快捷键。
 * 只响应单独的修饰键（带 Shift、Alt 的组合不算），按住不放不重复触发；命中后阻止浏览器默认行为。
 */
function useModifierHotkey(
  match: (key: string) => boolean,
  onTrigger: (key: string) => void,
  enabled = true,
) {
  const matchRef = React.useRef(match)
  const triggerRef = React.useRef(onTrigger)
  React.useEffect(() => {
    matchRef.current = match
    triggerRef.current = onTrigger
  })

  React.useEffect(() => {
    if (!enabled) return
    function handleKeyDown(event: KeyboardEvent) {
      if (event.defaultPrevented || event.repeat || event.isComposing) return
      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.shiftKey)
        return
      if (!matchRef.current(event.key)) return
      event.preventDefault()
      triggerRef.current(event.key)
    }
    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [enabled])
}

export { formatShortcut, useIsApplePlatform, useModifierHotkey }

"use client"

import { ChevronsUpDownIcon, PlusIcon } from "lucide-react"

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/components/ui/sidebar"

import { formatLabel, type Sidebar02Labels } from "./config"
import { formatShortcut, useIsApplePlatform } from "./shortcuts"
import type { Sidebar02Team } from "./types"

/** 方形团队标识：有图标用图标，否则用团队名的第一个字。 */
function TeamMark({ team }: { team: Sidebar02Team }) {
  return (
    <div
      data-slot="sidebar-02-team-mark"
      aria-hidden="true"
      className="flex aspect-square size-8 shrink-0 items-center justify-center rounded-md bg-sidebar-primary text-sm font-medium text-sidebar-primary-foreground [&_svg]:size-4"
    >
      {team.icon ? <team.icon /> : team.name.trim().slice(0, 1)}
    </div>
  )
}

