import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from "@/components/ui/command"

import type { Sidebar02Labels } from "./config"
import type {
  Sidebar02NavGroup,
  Sidebar02NavItem,
  Sidebar02QuickAction,
} from "./types"

type SearchEntry = { item: Sidebar02NavItem; group?: string }

/** 搜索弹窗：可搜全部导航项与快捷操作，回车选中。 */
function SearchCommand({
  open,
  onOpenChange,
  groups,
  footerItems,
  quickActions,
  onSelectItem,
  onSelectAction,
  labels,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  groups: Sidebar02NavGroup[]
  footerItems: Sidebar02NavItem[]
  quickActions: Sidebar02QuickAction[]
  onSelectItem: (item: Sidebar02NavItem) => void
  onSelectAction: (action: Sidebar02QuickAction) => void
  labels: Sidebar02Labels
}) {
  const entries: SearchEntry[] = [
    ...groups.flatMap((group) =>
      group.items.map((item) => ({ item, group: group.label })),
    ),
    ...footerItems.map((item) => ({ item })),
  ]

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title={labels.searchTitle}
      description={labels.searchDescription}
    >
      <Command>
        <CommandInput placeholder={labels.searchPlaceholder} />
        <CommandList>
          <CommandEmpty>{labels.searchEmpty}</CommandEmpty>
          <CommandGroup heading={labels.searchPages}>
            {entries.map(({ item, group }) => (
              <CommandItem
                key={item.id}
                value={item.id}
                keywords={[item.label, group ?? ""]}
                onSelect={() => onSelectItem(item)}
              >
                <item.icon />
                {item.label}
                {group ? <CommandShortcut>{group}</CommandShortcut> : null}
              </CommandItem>
            ))}
          </CommandGroup>
          {quickActions.length > 0 ? (
            <CommandGroup heading={labels.searchActions}>
              {quickActions.map((action) => (
                <CommandItem
                  key={action.id}
                  value={action.id}
                  keywords={[action.label]}
                  onSelect={() => onSelectAction(action)}
                >
                  <action.icon />
                  {action.label}
                </CommandItem>
              ))}
            </CommandGroup>
          ) : null}
        </CommandList>
      </Command>
    </CommandDialog>
  )
}

export { SearchCommand }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }
